Lemma fake_untouched_of : forall L W,
  (forall iv, In iv W ->
     (snd iv <= al_fake L \/ al_fake L + 11571200 <= fst iv)
  /\ (snd iv <= shad (al_fake L) \/ shad (al_fake L) + shlen 11571200 <= fst iv)
  /\ (snd iv <= al_dtls L \/ al_dtls L + 4096 <= fst iv)
  /\ (snd iv <= 0xb3ee0 \/ 0xb3ee0 + 8 <= fst iv) /\ (snd iv <= 0x5ed288 \/ 0x5ed288 + 16 <= fst iv)
  /\ (snd iv <= 0x5ed298 \/ 0x5ed298 + 8 <= fst iv) /\ (snd iv <= 0x5ed2b8 \/ 0x5ed2b8 + 8 <= fst iv)
  /\ (snd iv <= 0x14beb1 \/ 0x14beb1 + 1 <= fst iv) /\ (snd iv <= 0x149d98 \/ 0x149d98 + 4 <= fst iv)) ->
